// ── source: vcx/platform/store_anchor_identity_test.v ──
// Tier-1 anchor/alias/merge expansion (#82, spec/core/canonical.md §2.8) seen
// through a LIVE [$store] consumer: the store keys docs on the strict canonical
// hash, so two documents that differ only in data-sharing (inline vs
// anchored/merged) get the SAME store-key and dedup to one logical doc. This is
// the store-level proof that §2.8 resolution is on the store's identity path.

fn sa_put_text(handle cx.Node, text string) string {
	r := store_stdlib_builtin_inner('store-put-doc-text', [handle, store_str(text)]) or {
		panic('put-doc-text: ${err.msg()}')
	}
	if is_err_value(r) {
		panic('put-doc-text returned error: ${sw_err_code(r)}')
	}
	return sw_scalar(r)
}

fn test_store_alias_equivalent_to_inline() {
	handle := store_open_impl('mem://anchor-id', '', '', false, true, map[string]string{})
	aliased := '[root [defaults &def timeout=30 retries=3] [*def]]'
	inline := '[root [defaults timeout=30 retries=3] [defaults timeout=30 retries=3]]'

	h_alias := sa_put_text(handle, aliased)
	h_inline := sa_put_text(handle, inline)
	assert h_alias == h_inline, 'an aliased doc must share the store-key of its inlined form (${h_alias} vs ${h_inline})'

	// The second put was a content-addressed no-op: exactly one logical doc.
	mut ms, _, ok := store_get_open(handle)
	assert ok, 'store handle must resolve'
	assert ms.doc_order.len == 1, 'alias-equivalent puts must dedup to one doc, got ${ms.doc_order.len}'
}

fn test_store_merge_equivalent_to_inline() {
	handle := store_open_impl('mem://anchor-id-merge', '', '', false, true, map[string]string{})
	merged := '[root [defaults &def timeout=30 retries=3] [production *def host=prod retries=5]]'
	inline := '[root [defaults timeout=30 retries=3] [production timeout=30 retries=5 host=prod]]'

	assert sa_put_text(handle, merged) == sa_put_text(handle, inline), 'a merged doc must share the store-key of its inlined form'
}

fn test_store_anchor_doc_round_trips() {
	handle := store_open_impl('mem://anchor-rt', '', '', false, true, map[string]string{})
	h := sa_put_text(handle, '[root [defaults &def timeout=30] [*def]]')
	r := store_stdlib_builtin_inner('store-get-doc-text', [handle, store_str(h)]) or {
		panic('get-doc-text: ${err.msg()}')
	}
	assert r is cx.ScalarNode, 'stored anchored doc must round-trip'
	got := sw_scalar(r)
	// The reconstructed doc is the resolved (anchor-free) form.
	assert !got.contains('&def'), 'round-trip must be the resolved form: ${got}'
	assert !got.contains('[*def]'), 'round-trip must be the resolved form: ${got}'
}

// ── source: vcx/platform/store_blob_surface_test.v ──
// F1' blob-surface battery (RULED 2026-08-08): the OPAQUE-document pair —
// identity = hash of the RAW bytes, byte-exact round-trip, verify-on-read.
// Covers the lanes the capability-free corpus matrix cannot reach: file://
// persistence across reopen on BOTH models (pack manifest 'B' records +
// flat-index 'B' records), migrate carrying blobs kind-preserving, and the
// read-boundary integrity check refusing a corrupted flat record.

const bs_greet = "[?def greet (\$name) [str-format 'hello, {}' \$name]]"

fn bs_root(tag string) string {
	return os.join_path(os.temp_dir(), 'cx-blob-surface-${os.getpid()}-${tag}')
}

fn bs_open(url string) cx.Node {
	caps_set_all() // file substrates gate on the write capability
	h := store_open_impl(url, '', '', false, true, map[string]string{})
	if is_err_value(h) {
		panic('open ${url} failed: ${render_canonical(h)}')
	}
	return h
}

fn bs_str_of(n cx.Node) string {
	if n is cx.ScalarNode {
		return cx.scalar_value_str_public(n.value)
	}
	if n is cx.TextNode {
		return n.value
	}
	return ''
}

// pack (subtree) model: blob survives close/reopen via the 'B' manifest
// record, byte-exact, and the load path rehash-verifies.
fn test_blob_persists_pack_model() {
	root := bs_root('pack')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	h := bs_open('file://${root}')
	put := store_stdlib_builtin_inner('store-put-blob', [h, store_str(bs_greet)]) or {
		panic('put: ${err}')
	}
	key := bs_str_of(put)
	assert key.starts_with('sha2-256:'), 'blob key shape: ${render_canonical(put)}'
	store_stdlib_builtin_inner('store-close', [h]) or { panic('close: ${err}') }

	h2 := bs_open('file://${root}')
	got := store_stdlib_builtin_inner('store-get-blob', [h2, store_str(key)]) or {
		panic('get after reopen: ${err}')
	}
	assert bs_str_of(got) == bs_greet, 'pack reopen not byte-exact: ${bs_str_of(got)}'
}

// flat (document) model: same contract via the flat-index 'B' record.
fn test_blob_persists_flat_model() {
	root := bs_root('flat')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	h := bs_open('document+file://${root}')
	put := store_stdlib_builtin_inner('store-put-blob', [h, store_str(bs_greet)]) or {
		panic('put: ${err}')
	}
	key := bs_str_of(put)
	store_stdlib_builtin_inner('store-close', [h]) or { panic('close: ${err}') }

	h2 := bs_open('document+file://${root}')
	got := store_stdlib_builtin_inner('store-get-blob', [h2, store_str(key)]) or {
		panic('get after reopen: ${err}')
	}
	assert bs_str_of(got) == bs_greet, 'flat reopen not byte-exact: ${bs_str_of(got)}'
}

// migrate carries blobs kind-preserving: same key on the destination,
// byte-exact bytes, structured docs unaffected alongside.
fn test_blob_migrate_kind_preserving() {
	src := bs_open('mem://blob-mig-src')
	put := store_stdlib_builtin_inner('store-put-blob', [src, store_str(bs_greet)]) or {
		panic('put: ${err}')
	}
	key := bs_str_of(put)
	store_stdlib_builtin_inner('store-put-doc-text', [src, store_str('[order id=1 total=99.5]')]) or {
		panic('put doc: ${err}')
	}
	dst := bs_open('mem://blob-mig-dst')
	store_stdlib_builtin_inner('store-migrate', [src, dst]) or { panic('migrate: ${err}') }
	got := store_stdlib_builtin_inner('store-get-blob', [dst, store_str(key)]) or {
		panic('get on dest: ${err}')
	}
	assert bs_str_of(got) == bs_greet, 'migrated blob not byte-exact'
}

// the read boundary REFUSES a corrupted blob: flip a byte in the flat index
// payload and the next get must be an integrity error, never silent bytes.
fn test_blob_read_verify_refuses_corruption() {
	root := bs_root('corrupt')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	h := bs_open('document+file://${root}')
	put := store_stdlib_builtin_inner('store-put-blob', [h, store_str(bs_greet)]) or {
		panic('put: ${err}')
	}
	key := bs_str_of(put)
	store_stdlib_builtin_inner('store-close', [h]) or { panic('close: ${err}') }

	// corrupt the stored payload on disk (flip 'greet' -> 'gr33t' keeps length)
	idx := os.join_path(root, 'store.cxstore')
	mut files := []string{}
	if os.exists(idx) {
		files << idx
	} else {
		for e in os.ls(root) or { []string{} } {
			files << os.join_path(root, e)
		}
	}
	mut corrupted := false
	for f in files {
		raw := os.read_file(f) or { continue }
		if raw.contains('greet') {
			os.write_file(f, raw.replace('greet', 'gr33t')) or { continue }
			corrupted = true
		}
	}
	assert corrupted, 'test setup: found no on-disk payload to corrupt in ${files}'

	h2 := bs_open('document+file://${root}')
	if got := store_stdlib_builtin_inner('store-get-blob', [h2, store_str(key)]) {
		// an err VALUE is the expected refusal shape
		rendered := render_canonical(got)
		assert rendered.contains('CXER1120'), 'corrupted blob must refuse CXER1120, got: ${rendered}'
	} else {
		// a thrown error is also a loud refusal — acceptable
		assert true
	}
}

// ── source: vcx/platform/store_cluster_residuals_test.v ──
// store_cluster_residuals_test.v — the CODE residuals of the W0 spec-cluster
// issues #203/#204/#205 (the spec halves graduated in #225). #204 unknown-store
// wire code, #205 subtree+ reject / unsupported-param / compression fail-closed.

fn wr_req(method string, path string) cx.Element {
	// S3 (G3a): data ops reach the daemon ONLY as the gRPC edge's synthesized
	// pipeline="profile" requests — a raw HTTP data op is bootstrap-404. This
	// harness drives the data path, so it carries the pipeline attr; the
	// store-name RESOLUTION (unknown → CXER1710) is what it pins.
	return cx.Element{
		name:  'request'
		attrs: [
			cx.Attribute{
				name:  'method'
				value: cx.ScalarValue(method)
			},
			cx.Attribute{
				name:  'path'
				value: cx.ScalarValue(path)
			},
			cx.Attribute{
				name:  'pipeline'
				value: cx.ScalarValue('profile')
			},
		]
		items: [
			cx.Node(cx.Element{
				name:  'headers'
				items: []
			}),
		]
	}
}

fn wr_err_code(n cx.Node) string {
	if n is cx.Element && n.name == 'err' {
		for a in n.attrs {
			if a.name == 'code' {
				return cx.scalar_value_str_public(a.value)
			}
		}
	}
	return ''
}

fn wr_body(n cx.Node) string {
	if n is cx.Element {
		for it in n.items {
			if it is cx.Element && it.name == 'body' {
				for b in it.items {
					if b is cx.ScalarNode {
						return sw_scalar(b)
					}
				}
			}
		}
	}
	return ''
}

fn wr_status(n cx.Node) int {
	if n is cx.Element {
		for a in n.attrs {
			if a.name == 'status' {
				return cx.scalar_value_str_public(a.value).int()
			}
		}
	}
	return 0
}

// ── #204: data-op on an unknown store-name → 404 CXER1710 (not std-lib 1121) ──

fn test_dataop_unknown_store_1710() {
	mut s := new_service_state()
	s.mark_ready()
	caps_set_all()
	ctx := ServeContext{
		mounts: {
			'docs': store_open_impl('mem://wr-204', '', '', false, true, map[string]string{})
		}
	}
	resp := svc_handle_request(wr_req("POST", '/cx-store/v1/nope/list'),
		mut s, ctx)
	assert wr_status(resp) == 404, 'unknown-store data op → 404'
	assert wr_body(resp).contains('CXER1710'), 'unknown-store wire code is CXER1710 (#204, not std-lib 1121): ${wr_body(resp)}'
	assert !wr_body(resp).contains('CXER1121'), 'std-lib CXER1121 must not ride the wire'
}

