// ── source: vcx/platform/store_crash_consistency_test.v ──
// store_crash_consistency_test.v — #624: a file:// cxpack store survives an
// unclean shutdown at ANY point with a clean verdict — either it opens (at
// worst discarding the torn, never-acknowledged tail record) or it refuses
// with a typed integrity error. Never a crash, never data loss of an acked
// record, never a silently partial view. Pins the three crash windows the
// pre-#624 write path lost to, plus the WAL torn-tail discard.

fn cc_root(tag string) string {
	return os.join_path(os.temp_dir(), 'cxpack_crash_${tag}_${os.getpid()}')
}

fn cc_new(root string) &MemStore {
	return &MemStore{
		url:     'file://${root}'
		backend: 'cxpack'
		root:    root
		is_open: true
	}
}

fn cc_put(mut ms MemStore, text string) string {
	doc := cx.parse(text) or { panic('parse: ${text}') }
	c := render_canonical(doc.elements[0])
	h := cx.cx_text_hash(c) or { panic('hash') }
	store_put_canonical(mut ms, h, c) or { panic('put: ' + err.msg()) }
	store_cxpack_flush(mut ms) or { panic('flush: ${err.msg()}') }
	return h
}

// The pre-#624 compaction CRASH WINDOW: the pack fold had already destroyed
// GC'd objects while the OLD append-log manifest (with its superseded /
// tombstoned lines) was still on disk. With the reordered compaction the
// window no longer exists going forward, and the two-pass replay makes a
// store already damaged that way load cleanly: its dangling doc references
// are all tombstoned later in the same log, and only the FINAL live state is
// verified.
fn test_pre624_compaction_crash_window_store_recovers() {
	root := cc_root('window')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	mut ms := cc_new(root)
	keep := cc_put(mut ms, '[keep [k 1]]')
	doomed := cc_put(mut ms, '[doomed [unique "not-shared-with-keep"] [deep [x "y"]]]')
	store_delete_local(mut ms, doomed)
	store_cxpack_flush(mut ms) or { panic('flush: ${err.msg()}') } // T tombstone appended
	// Simulate the old-ordering crash: objects GC'd (compacted pack + segments
	// replaced by the live set) while the APPEND-LOG manifest survives.
	old_manifest := os.read_file(os.join_path(root, cxpack_manifest)) or { panic('read manifest') }
	store_cxpack_compact(mut ms) or { panic('compact: ${err.msg()}') }
	os.write_file(os.join_path(root, cxpack_manifest), old_manifest) or { panic('write manifest') }

	mut ms2 := cc_new(root)
	store_cxpack_load(mut ms2) or {
		panic('a pre-#624 crash-window store must RECOVER, got: ${err.msg()}')
	}
	assert ms2.doc_order == [keep], 'live doc must survive recovery (got ${ms2.doc_order})'
	assert store_doc_present(ms2, keep)
	assert !store_doc_present(ms2, doomed), 'tombstoned doc must stay gone'
}

// TORN TAIL: a kill mid-append tears the manifest's final line structurally.
// The record was never acknowledged (its flush never returned) — the loader
// discards it loudly and opens at the last whole state. An acked (whole)
// record is never dropped.
fn test_torn_manifest_tail_is_discarded_not_fatal() {
	root := cc_root('torn')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	mut ms := cc_new(root)
	h1 := cc_put(mut ms, '[a [x 1]]')
	h2 := cc_put(mut ms, '[b [y 2]]')
	mp := os.join_path(root, cxpack_manifest)
	whole := os.read_file(mp) or { panic('read manifest') }
	// tear the final record mid-hash (what a kill mid-write leaves)
	assert whole.ends_with('\n')
	torn := whole[..whole.len - 20]
	os.write_file(mp, torn) or { panic('write torn') }

	mut ms2 := cc_new(root)
	store_cxpack_load(mut ms2) or { panic('torn tail must not refuse the store: ${err.msg()}') }
	// h1's records are earlier lines — the acked doc survives; the torn final
	// record is discarded (whichever doc/alias it carried).
	assert store_doc_present(ms2, h1), 'acked doc lost to a torn tail'
	assert ms2.doc_order.len >= 1
	// a torn line ANYWHERE ELSE stays a hard integrity error
	mut mid := whole.split_into_lines().filter(it.trim_space() != '')
	assert mid.len >= 2
	mid[0] = mid[0][..mid[0].len - 5] // tear the FIRST record instead
	os.write_file(mp, mid.join('\n') + '\n') or { panic('write mid-torn') }
	mut ms3 := cc_new(root)
	if _ := store_cxpack_load(mut ms3) {
		assert false, 'a torn NON-final record must be a hard integrity error'
	} else {
		assert ms3.doc_order.len == 0, 'refused load must leave no partial state'
	}
	_ = h2
}

// A kill mid-segment-write must never expose a torn pack at a segment's final
// name: the writer goes through a temp sibling + atomic rename, discovery
// ignores the .tmp, and the store reopens whole without the in-flight flush.
fn test_stray_segment_tmp_is_ignored() {
	root := cc_root('tmpseg')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	mut ms := cc_new(root)
	h1 := cc_put(mut ms, '[a [x 1]]')
	// what a kill mid-flush_segment leaves: a partial pack at the temp name
	next_seg := os.join_path(root, cxpack_seg_name(ms.obj_pack.segment_count()))
	os.write_file(next_seg + '.tmp', 'PARTIAL-GARBAGE-NOT-A-PACK') or { panic('write tmp') }

	mut ms2 := cc_new(root)
	store_cxpack_load(mut ms2) or { panic('a stray segment .tmp must be invisible: ${err.msg()}') }
	assert store_doc_present(ms2, h1)
	// and a TRUNCATED pack at a FINAL segment name (pre-#624 direct writes
	// could leave one) refuses with a typed error — never a crash.
	seg0 := os.join_path(root, cxpack_seg_name(0))
	whole := os.read_bytes(seg0) or { panic('read seg0') }
	os.write_file_array(seg0, whole[..whole.len / 2]) or { panic('truncate seg0') }
	mut ms3 := cc_new(root)
	if _ := store_cxpack_load(mut ms3) {
		assert false, 'a truncated pack at a final segment name must refuse loudly'
	}
}

// Corrupt pack internals (a lying index count / garbage entry offsets) yield
// typed refusals from the reader — pinned at the cxstore layer so the mmap
// path can never walk out of bounds (#624's SIGBUS leg).
fn test_pack_reader_bounds_are_checked() {
	root := cc_root('bounds')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	os.mkdir_all(root) or { panic(err) }
	p := os.join_path(root, 'p.cxpack')
	cxstore.write_pack(p, ['payload-one'.bytes(), 'payload-two'.bytes()]) or { panic(err.msg()) }
	mut data := os.read_bytes(p) or { panic('read pack') }
	// footer layout: …[index_count u32][records]…[footer_crc32][flen u64].
	// Overwrite index_count with a huge value AND refresh the footer crc so
	// the count check (not the crc) is what refuses.
	flen := int(u64(data[data.len - 8]) | (u64(data[data.len - 7]) << 8) | (u64(data[data.len - 6]) << 16) | (u64(data[data.len - 5]) << 24))
	fstart := data.len - 8 - flen
	data[fstart] = 0xff
	data[fstart + 1] = 0xff
	data[fstart + 2] = 0xff
	data[fstart + 3] = 0x7f
	refreshed := crc32.sum(data[fstart..data.len - 12])
	data[data.len - 12] = u8(refreshed & 0xff)
	data[data.len - 11] = u8((refreshed >> 8) & 0xff)
	data[data.len - 10] = u8((refreshed >> 16) & 0xff)
	data[data.len - 9] = u8((refreshed >> 24) & 0xff)
	os.write_file_array(p, data) or { panic('rewrite') }
	if _ := cxstore.open_pack(p) {
		assert false, 'a pack whose index count exceeds its footer must refuse'
	}
}

// ── source: vcx/platform/store_document_model_test.v ──
// §6 + §4.6 for the DEGENERATE document model (#129 B2): `model=document` stores each
// doc as ONE object ("don't decompose") on any object-graph substrate, reusing the
// same seam + store_graph refs/replay. The model is INVISIBLE to the Layer-1 API:
// the same doc has the same store-key and the same byte-identical round-trip under
// both models; the only observable difference is object count (document = 1/doc,
// subtree = many) — i.e. document trades dedup for simplicity.

fn dm_canon_hash(text string) (string, string) {
	c := render_canonical(cx.parse(text) or { panic('parse: ${err.msg()}') }.elements[0])
	h := cx.cx_text_hash(c) or { panic('hash: ${err.msg()}') }
	return c, h
}

fn test_document_model_mem_api_invisibility() {
	text := '[order [id 1] [customer [name "Acme"] [addr [city "NYC"] [zip "10001"]]]]'
	c, h := dm_canon_hash(text)

	// document model (mem)
	mut doc_ms := &MemStore{
		backend: 'mem'
		is_open: true
		model:   'document'
	}
	assert store_objgraph_active(doc_ms)
	store_put_canonical(mut doc_ms, h, c) or { panic('doc put: ${err.msg()}') }
	got_doc := store_doc_text(doc_ms, h) or { panic('doc get: ${err.msg()}') }
	doc_objs := doc_ms.obj_sink.objects.len

	// subtree model (mem, default)
	mut sub_ms := &MemStore{
		backend: 'mem'
		is_open: true
	}
	store_put_canonical(mut sub_ms, h, c) or { panic('sub put: ${err.msg()}') }
	got_sub := store_doc_text(sub_ms, h) or { panic('sub get: ${err.msg()}') }
	sub_objs := sub_ms.obj_sink.objects.len

	// API-invisible: identical store-key (same h used) + identical round-trip text.
	assert got_doc == c, 'document round-trip not byte-identical'
	assert got_sub == c, 'subtree round-trip not byte-identical'
	assert got_doc == got_sub, 'document and subtree must return identical text for the same doc'
	// The model shows ONLY in object count: document = exactly 1 object, subtree = many.
	assert doc_objs == 1, 'document model must store exactly one object per doc, got ${doc_objs}'
	assert sub_objs > 1, 'subtree model must decompose into multiple objects, got ${sub_objs}'
}

fn test_document_model_cxobj_reopen() {
	root := os.join_path(os.temp_dir(), 'cxobj_docmodel_${os.getpid()}')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	c, h := dm_canon_hash('[note [meta [author "ep"]] [body "hello document model"]]')

	mut ms := &MemStore{
		backend: 'cxobj'
		root:    root
		is_open: true
		model:   'document'
	}
	store_cxobj_backend(mut ms) or { panic('attach: ${err.msg()}') }
	store_put_canonical(mut ms, h, c) or { panic('put: ${err.msg()}') }
	store_cxobj_flush(mut ms) or { panic('flush: ${err.msg()}') }

	// reopen with model=document → replay restores the raw object (no decompose),
	// round-trip byte-identical.
	mut ms2 := &MemStore{
		backend: 'cxobj'
		root:    root
		is_open: true
		model:   'document'
	}
	store_cxobj_load(mut ms2) or { panic('reopen: ${err.msg()}') }
	assert store_doc_present(ms2, h), 'doc must survive a document-mode reopen'
	got := store_doc_text(ms2, h) or { panic('get: ${err.msg()}') }
	assert got == c, 'document reopen round-trip not byte-identical'
}

// #129 PR-H: the canonical `document+` URI prefix selects the document model on
// the mem / sqlite / s3 substrates (consistent with file://), and a bare substrate
// URI is subtree by default — both via the live open dispatcher (not just opts).
fn test_document_prefix_open_dispatch() {
	// document+mem:// → document model (hermetic; mem is capability-free).
	h := store_open_impl('document+mem://', '', '', false, true, map[string]string{})
	id := store_handle_of(h) or { panic('document+mem:// did not return a handle: ${h}') }
	ms := store_lookup(id) or { panic('no store for document+mem://') }
	assert ms.backend == 'mem', 'document+mem:// substrate should be mem, got ${ms.backend}'
	assert ms.model == 'document', 'document+mem:// must select the document model'

	// bare mem:// → subtree default.
	h2 := store_open_impl('mem://', '', '', false, true, map[string]string{})
	ms2 := store_lookup(store_handle_of(h2) or { panic('no handle for mem://') }) or {
		panic('no store for mem://')
	}
	assert ms2.model == '', 'bare mem:// must be the subtree default, got model=${ms2.model}'

	// the legacy [opts model=document] surface still selects document (back-compat).
	h3 := store_open_impl('mem://', '', '', false, true, {
		'model': 'document'
	})
	ms3 := store_lookup(store_handle_of(h3) or { panic('no handle for opts mem://') }) or {
		panic('no store for opts mem://')
	}
	assert ms3.model == 'document', '[opts model=document] must still select document'
}

// ── source: vcx/platform/store_flat_file_test.v ──
// store_flat_file_test.v — flat file:// document-model parity + hygiene
// (#290 / #291 / #292). The flat model is the LEGACY on-disk form (new file://
// stores land on the cxpack object graph), but pre-existing stores replay
// through it forever, so it keeps the same contracts:
//
//   #290 gc/prune succeed per the store.md §15 capability table (flat
//        semantics: every present doc is its own object AND a root, mirroring
//        pc_reclaim's obj_roots semantics — reclaimed=0, objects=len(docs);
//        gc additionally compacts the append log to a snapshot).
//   #291 delete-doc appends a T (tombstone) record — the O(1) append path —
//        instead of rewriting the whole snapshot; store_read_index replays it;
//        the compaction heuristic folds tombstones away; an OLD index (no
//        tombstones) replays identically; a re-put after a tombstone comes back.
//   #292 open sweeps stale sibling `.cxstore-index.tmp.<pid>` files whose pid
//        is no longer a live process (crash between temp write and rename).
//   #298 delete-alias appends an X (alias tombstone) record — the #291
//        contract on the alias plane (durability, re-add ordering, compaction).

fn ff_root(tag string) string {
	root := os.join_path(os.temp_dir(), 'cxflat_${tag}_${os.getpid()}')
	os.rmdir_all(root) or {}
	return root
}

// ff_open opens (or reopens) a flat document-model store at root via the
// PUBLIC open path (self-describing reopen included), with all caps granted.
fn ff_open(url string, read_only bool) cx.Node {
	caps_set_all()
	h := store_open_impl(url, '', '', read_only, true, map[string]string{})
	store_handle_of(h) or { panic('flat open ${url} did not return a handle: ${h}') }
	return h
}

fn ff_ms(h cx.Node) &MemStore {
	id := store_handle_of(h) or { panic('no handle: ${h}') }
	return store_lookup(id) or { panic('no store for handle ${id}') }
}

fn ff_put(h cx.Node, text string) string {
	r := store_stdlib_builtin_inner('store-put-doc-text', [h, store_str(text)]) or {
		panic('put: ${err.msg()}')
	}
	assert !is_err_value(r), 'put must succeed: ${r}'
	return sw_scalar(r)
}

fn ff_get(h cx.Node, hash string) cx.Node {
	return store_stdlib_builtin_inner('store-get-doc-text', [h, store_str(hash)]) or {
		panic('get: ${err.msg()}')
	}
}

fn ff_delete(h cx.Node, hash string) cx.Node {
	return store_stdlib_builtin_inner('store-delete-doc', [h, store_str(hash)]) or {
		panic('delete: ${err.msg()}')
	}
}

fn ff_err_code(n cx.Node) string {
	if !is_err_value(n) {
		return ''
	}
	if n is cx.Element {
		return sw_attr(n, 'code')
	}
	return ''
}

fn ff_attr_int(n cx.Node, name string) int {
	if n is cx.Element {
		return sw_attr(n, name).int()
	}
	return -999
}

fn ff_index_path(root string) string {
	return os.join_path(root, store_index_name)
}

// ff_canon_hash produces the STRICT canonical text + its genuine store key —
// the same canonical.md §1.2 identity put-doc-text computes (needed when
// fabricating an index by hand and when asserting round-trip bytes).
fn ff_canon_hash(text string) (string, string) {
	c := cx.cx_text_canonical(text) or { panic('canonical: ${err.msg()}') }
	h := cx.cx_text_hash(c) or { panic('hash: ${err.msg()}') }
	return c, h
}

// ── #290: gc / prune succeed on the flat model ────────────────────────────────

fn test_flat_prune_succeeds_with_flat_semantics() {
	root := ff_root('prune')
	defer {
		os.rmdir_all(root) or {}
	}
	h := ff_open('document+file://${root}', false)
	ff_put(h, '[doc [item "x"]]')
	ka := ff_put(h, '[doc [item "y"]]')
	d := ff_delete(h, ka)
	assert !is_err_value(d), 'delete must succeed: ${d}'
	r := store_stdlib_builtin_inner('store-prune', [h]) or { panic('prune: ${err.msg()}') }
	assert !is_err_value(r), 'prune on flat file:// must succeed per §15, got ${r}'
	assert r is cx.Element && (r as cx.Element).name == 'prune-result', 'prune result shape: ${r}'
	// flat semantics: every present doc is its own object and a root — nothing
	// sub-doc to reclaim, honest zero.
	assert ff_attr_int(r, 'reclaimed') == 0, 'flat prune reclaims nothing: ${r}'
	assert ff_attr_int(r, 'objects') == 1, 'flat prune reports live docs as objects: ${r}'
}

fn test_flat_prune_empty_store() {
	root := ff_root('prune_empty')
	defer {
		os.rmdir_all(root) or {}
	}
	h := ff_open('document+file://${root}', false)
	r := store_stdlib_builtin_inner('store-prune', [h]) or { panic('prune: ${err.msg()}') }
	assert !is_err_value(r), 'prune on an empty flat store must succeed: ${r}'
	assert ff_attr_int(r, 'reclaimed') == 0 && ff_attr_int(r, 'objects') == 0, 'empty flat prune: ${r}'
}

fn test_flat_gc_succeeds_and_compacts_log() {
	root := ff_root('gc')
	defer {
		os.rmdir_all(root) or {}
	}
	h := ff_open('document+file://${root}', false)
	keep := ff_put(h, '[doc [item "keep"]]')
	gone := ff_put(h, '[doc [item "gone"]]')
	ff_delete(h, gone)
	r := store_stdlib_builtin_inner('store-gc', [h]) or { panic('gc: ${err.msg()}') }
	assert !is_err_value(r), 'gc on flat file:// must succeed per §15, got ${r}'
	assert r is cx.Element && (r as cx.Element).name == 'gc-result', 'gc result shape: ${r}'
	assert ff_attr_int(r, 'reclaimed') == 0, 'flat gc reclaims nothing sub-doc: ${r}'
	assert ff_attr_int(r, 'objects') == 1, 'flat gc reports live docs as objects: ${r}'
	// gc = prune + compaction: the on-disk index is now a snapshot of live state
	// (one D record for the kept doc, no tombstones, no stale records).
	mut ms := ff_ms(h)
	raw := os.read_file(ff_index_path(root)) or { panic('read index: ${err.msg()}') }
	assert raw.contains('D\t${keep}\t'), 'compacted snapshot keeps the live doc'
	assert !raw.contains('D\t${gone}\t'), 'compacted snapshot drops the deleted doc record'
	assert !raw.contains('T\t'), 'compacted snapshot carries no tombstones'
	assert ms.log_records == ms.doc_order.len + ms.alias_order.len, 'gc resets the log to live size, got ${ms.log_records}'
	// live state intact + durable
	h2 := ff_open('file://${root}', false)
	keep_c, _ := ff_canon_hash('[doc [item "keep"]]')
	assert sw_scalar(ff_get(h2, keep)) == keep_c, 'kept doc round-trips after gc'
}

fn test_flat_gc_prune_read_only_still_denied() {
	root := ff_root('gc_ro')
	defer {
		os.rmdir_all(root) or {}
	}
	h := ff_open('document+file://${root}', false)
	ff_put(h, '[doc [item "x"]]')
	ro := ff_open('file://${root}', true)
	g := store_stdlib_builtin_inner('store-gc', [ro]) or { panic('gc: ${err.msg()}') }
	assert ff_err_code(g) == 'cx-err:CXER1110', 'gc on a read-only flat store stays denied: ${g}'
	p := store_stdlib_builtin_inner('store-prune', [ro]) or { panic('prune: ${err.msg()}') }
	assert ff_err_code(p) == 'cx-err:CXER1110', 'prune on a read-only flat store stays denied: ${p}'
}

// ── #291: delete-doc appends a tombstone, replayed on open ───────────────────

fn test_flat_delete_appends_tombstone_not_snapshot() {
	root := ff_root('tomb')
	defer {
		os.rmdir_all(root) or {}
	}
	h := ff_open('document+file://${root}', false)
	ka := ff_put(h, '[doc [item "a"]]')
	kb := ff_put(h, '[doc [item "b"]]')
	d := ff_delete(h, ka)
	assert d is cx.ScalarNode && sw_scalar(d) == 'true', 'delete of a present doc returns true: ${d}'
	raw := os.read_file(ff_index_path(root)) or { panic('read index: ${err.msg()}') }
	// O(1) append path: the log carries the ORIGINAL D record AND the T record —
	// no whole-snapshot rewrite happened.
	assert raw.contains('T\t${ka}\t'), 'delete must append a tombstone record, index:\n${raw}'
	assert raw.contains('D\t${ka}\t'), 'the original D record stays in the log (append, not rewrite)'
	assert raw.contains('D\t${kb}\t'), 'unrelated doc record intact'
	// tombstone replays on reopen: deleted doc absent, sibling present.
	h2 := ff_open('file://${root}', false)
	ms2 := ff_ms(h2)
	assert ka !in ms2.docs, 'tombstoned doc must not replay'
	b_c, _ := ff_canon_hash('[doc [item "b"]]')
	assert sw_scalar(ff_get(h2, kb)) == b_c, 'sibling doc replays intact'
	// deleting an absent doc is a clean false, and appends nothing new.
	before := os.file_size(ff_index_path(root))
	d2 := ff_delete(h2, ka)
	assert d2 is cx.ScalarNode && sw_scalar(d2) == 'false', 'delete of an absent doc returns false'
	assert os.file_size(ff_index_path(root)) == before, 'a no-op delete appends no record'
}

fn test_flat_old_index_without_tombstones_replays_identically() {
	root := ff_root('oldidx')
	defer {
		os.rmdir_all(root) or {}
	}
	// Fabricate a pre-tombstone index EXACTLY as the old writer laid it out:
	// header + D records + A record. This is the #291 back-compat contract.
	c1, h1 := ff_canon_hash('[user name=al]')
	c2, h2 := ff_canon_hash('[user name=bo]')
	os.mkdir_all(root) or { panic('mkdir: ${err.msg()}') }
	mut content := 'CXSTORE\tv1\n'
	content += store_doc_record(h1, c1)
	content += store_doc_record(h2, c2)
	content += store_alias_record('current', h1)
	os.write_file(ff_index_path(root), content) or { panic('write: ${err.msg()}') }
	// bare file:// reopen (self-describing detection picks the flat model).
	h := ff_open('file://${root}', false)
	ms := ff_ms(h)
	assert ms.model == 'document', 'legacy index reopens as the flat document model'
	assert ms.doc_order == [h1, h2], 'doc order preserved from the old index'
	assert sw_scalar(ff_get(h, h1)) == c1, 'old doc 1 replays byte-identically'
	assert sw_scalar(ff_get(h, h2)) == c2, 'old doc 2 replays byte-identically'
	assert ms.aliases['current'] == h1, 'old alias replays'
	assert ms.log_records == 3, 'replay seeds the log count from the inherited records'
}

fn test_flat_tombstoned_doc_reput_comes_back() {
	root := ff_root('reput')
	defer {
		os.rmdir_all(root) or {}
	}
	h := ff_open('document+file://${root}', false)
	k := ff_put(h, '[doc [item "phoenix"]]')
	ff_delete(h, k)
	k2 := ff_put(h, '[doc [item "phoenix"]]')
	assert k2 == k, 'same content re-puts under the same hash'
	// replay order semantics: D, T, D → the doc is PRESENT after reopen.
	ha := ff_open('file://${root}', false)
	phoenix_c, _ := ff_canon_hash('[doc [item "phoenix"]]')
	assert sw_scalar(ff_get(ha, k)) == phoenix_c, 're-put after tombstone must come back on replay'
	// and a trailing tombstone wins again: D, T, D, T → absent.
	ff_delete(ha, k)
	hb := ff_open('file://${root}', false)
	msb := ff_ms(hb)
	assert k !in msb.docs, 'trailing tombstone must win on replay'
}

fn test_flat_delete_heavy_log_compacts() {
	root := ff_root('compact')
	defer {
		os.rmdir_all(root) or {}
	}
	h := ff_open('document+file://${root}', false)
	keep := ff_put(h, '[doc [item "base"]]')
	// 45 put+delete cycles = 90 log records against live=1 — well past the
	// store_append redundancy threshold (2*live + 64). Tombstones MUST count
	// toward redundancy so a delete-heavy log folds to a snapshot.
	for i in 0 .. 45 {
		k := ff_put(h, '[doc [item "churn-${i}"]]')
		ff_delete(h, k)
	}
	ms := ff_ms(h)
	live := ms.doc_order.len + ms.alias_order.len
	assert live == 1, 'only the base doc stays live'
	// 91 records were appended against live=1; tombstones count toward the
	// redundancy measure, so compaction MUST have fired and the log stays
	// bounded by the store_append threshold (a tail of post-compaction appends
	// may legitimately remain, tombstones included).
	assert ms.log_records <= 2 * live + 64, 'delete-heavy log must have compacted, log_records=${ms.log_records}'
	raw := os.read_file(ff_index_path(root)) or { panic('read index: ${err.msg()}') }
	d_count := raw.count('D\t')
	t_count := raw.count('T\t')
	assert d_count + t_count == ms.log_records, 'on-disk records (${d_count}D + ${t_count}T) must match the log bookkeeping (${ms.log_records})'
	assert t_count < 45, 'compaction folds tombstoned records away, ${t_count} T records remain'
	// durability: the survivor replays.
	h2 := ff_open('file://${root}', false)
	base_c, _ := ff_canon_hash('[doc [item "base"]]')
	assert sw_scalar(ff_get(h2, keep)) == base_c, 'base doc survives compaction'
}

// ── #298: delete-alias appends an X tombstone, replayed on open ──────────────

fn ff_set_alias(h cx.Node, alias string, hash string) {
	r := store_stdlib_builtin_inner('store-set-alias', [h, store_str(alias), store_str(hash)]) or {
		panic('set-alias: ${err.msg()}')
	}
	assert !is_err_value(r), 'set-alias must succeed: ${r}'
}

fn ff_delete_alias(h cx.Node, alias string) cx.Node {
	return store_stdlib_builtin_inner('store-delete-alias', [h, store_str(alias)]) or {
		panic('delete-alias: ${err.msg()}')
	}
}

fn test_flat_delete_alias_appends_tombstone_not_snapshot() {
	root := ff_root('atomb')
	defer {
		os.rmdir_all(root) or {}
	}
	h := ff_open('document+file://${root}', false)
	k := ff_put(h, '[doc [item "target"]]')
	ff_set_alias(h, 'cur', k)
	ff_set_alias(h, 'other', k)
	d := ff_delete_alias(h, 'cur')
	assert d is cx.ScalarNode && sw_scalar(d) == 'true', 'delete-alias of a present alias returns true: ${d}'
	raw := os.read_file(ff_index_path(root)) or { panic('read index: ${err.msg()}') }
	// O(1) append path: the log carries the ORIGINAL A record AND the X record —
	// no whole-snapshot rewrite happened. X mirrors A's length-prefixed payload
	// shape (alias names may contain any bytes).
	assert raw.contains('X\t${'cur'.len}\t0\ncur\n'), 'delete-alias must append an X tombstone, index:\n${raw}'
	assert raw.contains('A\t${'cur'.len}\t${k}\ncur\n'), 'the original A record stays in the log (append, not rewrite)'
	// tombstone replays on reopen: deleted alias absent, sibling present.
	h2 := ff_open('file://${root}', false)
	ms2 := ff_ms(h2)
	assert 'cur' !in ms2.aliases, 'tombstoned alias must not replay'
	assert 'cur' !in ms2.alias_order, 'tombstoned alias must leave alias_order'
	assert ms2.aliases['other'] == k, 'sibling alias replays intact'
	// deleting an absent alias is a clean false, and appends nothing new.
	before := os.file_size(ff_index_path(root))
	d2 := ff_delete_alias(h2, 'cur')
	assert d2 is cx.ScalarNode && sw_scalar(d2) == 'false', 'delete-alias of an absent alias returns false'
	assert os.file_size(ff_index_path(root)) == before, 'a no-op delete-alias appends no record'
}

fn test_flat_alias_tombstone_reset_comes_back() {
	root := ff_root('areset')
	defer {
		os.rmdir_all(root) or {}
	}
	h := ff_open('document+file://${root}', false)
	k1 := ff_put(h, '[doc [item "v1"]]')
	k2 := ff_put(h, '[doc [item "v2"]]')
	ff_set_alias(h, 'ptr', k1)
	ff_delete_alias(h, 'ptr')
	ff_set_alias(h, 'ptr', k2)
	// replay order semantics: A, X, A → the alias is PRESENT at its LAST target.
	ha := ff_open('file://${root}', false)
	msa := ff_ms(ha)
	assert msa.aliases['ptr'] == k2, 're-set alias after tombstone must come back at the new target'
	assert msa.alias_order.filter(it == 'ptr').len == 1, 'alias_order holds the re-set alias exactly once'
	// and a trailing tombstone wins again: A, X, A, X → absent.
	ff_delete_alias(ha, 'ptr')
	hb := ff_open('file://${root}', false)
	msb := ff_ms(hb)
	assert 'ptr' !in msb.aliases, 'trailing alias tombstone must win on replay'
}

fn test_flat_delete_alias_heavy_log_compacts() {
	root := ff_root('acompact')
	defer {
		os.rmdir_all(root) or {}
	}
	h := ff_open('document+file://${root}', false)
	k := ff_put(h, '[doc [item "abase"]]')
	ff_set_alias(h, 'keep', k)
	// 45 set+delete cycles = 90 log records against live=2 (1 doc + 1 alias) —
	// past the store_append threshold (2*live + 64). Alias tombstones MUST count
	// toward redundancy so a delete-alias-heavy log folds to a snapshot.
	for i in 0 .. 45 {
		ff_set_alias(h, 'churn-${i}', k)
		ff_delete_alias(h, 'churn-${i}')
	}
	ms := ff_ms(h)
	live := ms.doc_order.len + ms.alias_order.len
	assert live == 2, 'only the base doc + kept alias stay live'
	assert ms.log_records <= 2 * live + 64, 'delete-alias-heavy log must have compacted, log_records=${ms.log_records}'
	raw := os.read_file(ff_index_path(root)) or { panic('read index: ${err.msg()}') }
	recs := raw.count('D\t') + raw.count('A\t') + raw.count('T\t') + raw.count('X\t')
	assert recs == ms.log_records, 'on-disk records (${recs}) must match the log bookkeeping (${ms.log_records})'
	assert raw.count('X\t') < 45, 'compaction folds alias-tombstoned records away, ${raw.count('X\t')} X records remain'
	// durability: the survivors replay.
	h2 := ff_open('file://${root}', false)
	ms2 := ff_ms(h2)
	assert ms2.aliases['keep'] == k, 'kept alias survives compaction'
}

// ── #292: open sweeps stale .cxstore-index.tmp.<pid> orphans ─────────────────

// ff_dead_pid returns a pid that is guaranteed not to be a live process: it
// spawns /usr/bin/true and waits for it to exit.
fn ff_dead_pid() int {
	mut p := os.new_process('/usr/bin/true')
	p.run()
	p.wait()
	assert p.pid > 0, 'spawn for dead-pid fixture failed'
	return p.pid
}

fn test_open_sweeps_stale_tmp_files() {
	root := ff_root('sweep')
	defer {
		os.rmdir_all(root) or {}
	}
	h := ff_open('document+file://${root}', false)
	k := ff_put(h, '[doc [item "survivor"]]')
	idx := ff_index_path(root)
	dead := ff_dead_pid()
	stale := '${idx}.tmp.${dead}'
	live_tmp := '${idx}.tmp.${os.getpid()}' // our own pid = a live writer's in-flight persist
	weird := '${idx}.tmp.not-a-pid' // unknown shape — never touched
	os.write_file(stale, '') or { panic('stale fixture: ${err.msg()}') }
	os.write_file(live_tmp, 'in-flight') or { panic('live fixture: ${err.msg()}') }
	os.write_file(weird, 'unknown') or { panic('weird fixture: ${err.msg()}') }
	// reopen → the dead writer's orphan is swept; everything else untouched.
	h2 := ff_open('file://${root}', false)
	assert !os.exists(stale), 'stale tmp from a dead pid must be swept at open'
	assert os.exists(live_tmp), 'a live pid tmp (in-flight persist) is never touched'
	assert os.exists(weird), 'non-pid-suffixed files are never touched'
	assert os.exists(idx), 'the live index is never touched'
	survivor_c, _ := ff_canon_hash('[doc [item "survivor"]]')
	assert sw_scalar(ff_get(h2, k)) == survivor_c, 'store content intact after sweep'
	os.rm(live_tmp) or {}
	os.rm(weird) or {}
}

fn test_read_only_open_does_not_sweep() {
	root := ff_root('sweep_ro')
	defer {
		os.rmdir_all(root) or {}
	}
	h := ff_open('document+file://${root}', false)
	ff_put(h, '[doc [item "x"]]')
	idx := ff_index_path(root)
	dead := ff_dead_pid()
	stale := '${idx}.tmp.${dead}'
	os.write_file(stale, '') or { panic('stale fixture: ${err.msg()}') }
	// a read-only open holds only the read grant — it must not delete files.
	ff_open('file://${root}', true)
	assert os.exists(stale), 'read-only open must not sweep (no write grant)'
	os.rm(stale) or {}
}

// ── source: vcx/platform/store_ft_test.v ──

fn test_store_ft_search_and_stemming() {
	dir := os.join_path(os.temp_dir(), 'cxstore_ft_rt')
	os.rmdir_all(dir) or {}
	mut repo := cxstore.open_repo(dir) or {
		assert false, 'open: ${err}'
		return
	}
	ka := repo.put_text('[doc [title "the quick brown fox"] [body "it jumps over"]]') or {
		assert false, 'putA: ${err}'
		return
	}
	kb := repo.put_text('[doc [title "a lazy sleeping dog"]]') or {
		assert false, 'putB: ${err}'
		return
	}

	ix := build_store_ft(repo)

	// term hits the right doc
	assert ix.search('quick') == [ka]
	assert ix.search('dog') == [kb]
	// Porter2 stemming: query 'jumping' stems to 'jump', matches 'jumps'
	assert ix.search('jumping') == [ka]
	// stopword-only query yields nothing
	assert ix.search('the') == []
	// absent term
	assert ix.search('zebra') == []
	// AND semantics: both terms in the same doc
	assert ix.search('quick fox') == [ka]
	assert ix.search('quick dog') == [] // not in the same doc

	os.rmdir_all(dir) or {}
}

fn test_store_ft_multi_doc_and_sidecar() {
	dir := os.join_path(os.temp_dir(), 'cxstore_ft_multi')
	os.rmdir_all(dir) or {}
	mut repo := cxstore.open_repo(dir) or {
		assert false, 'open: ${err}'
		return
	}
	k1 := repo.put_text('[log [entry "database error occurred"]]') or {
		assert false, 'put1: ${err}'
		return
	}
	k2 := repo.put_text('[log [entry "database connection restored"]]') or {
		assert false, 'put2: ${err}'
		return
	}
	ix := build_store_ft(repo)
	dbhits := ix.search('database')
	assert dbhits.len == 2
	assert k1 in dbhits && k2 in dbhits
	assert ix.search('error') == [k1]

	// sidecar round-trips
	sc := os.join_path(dir, 'ft.tsv')
	ix.save(sc) or {
		assert false, 'save: ${err}'
		return
	}
	ix2 := load_store_ft(sc) or {
		assert false, 'load: ${err}'
		return
	}
	assert ix2.search('database').len == 2
	assert ix2.search('error') == [k1]

	os.rmdir_all(dir) or {}
}

// ── source: vcx/platform/store_introspection_test.v ──
// store_introspection_test.v — #129-D: object-graph introspection (object_count
// + dedup ratio) surfaces through StoreStats / store_mount_stats and the
// /metrics exposition, ONLY for the content-addressed backend (no fabricated
// zeros for the flat backends), with the dedup walk cached against a mutation
// fingerprint.

fn ti_canon_hash(text string) (string, string) {
	doc := cx.parse(text) or { return text, '' }
	c := render_canonical(doc.elements[0])
	h := cx.cx_text_hash(c) or { return c, '' }
	return c, h
}

fn ti_put(mut ms MemStore, text string) {
	c, h := ti_canon_hash(text)
	store_put_canonical(mut ms, h, c) or { panic('put: ' + err.msg()) }
}

// a cxpack store reports object_count and a >1 dedup ratio once docs share
// subtrees; the engine-level stat walk distinguishes logical vs distinct.
fn test_objgraph_stats_object_count_and_dedup() {
	mut ms := &MemStore{
		backend: 'cxpack'
		root:    ''
		is_open: true
	}
	big := '[customer [name "Acme"] [addr [street "1 Main"] [city "NYC"] [zip "10001"]] [tags [t "a"] [t "b"] [t "c"]]]'
	ti_put(mut ms, '[order [id 1] ${big}]')
	ti_put(mut ms, '[order [id 2] ${big}]') // shares the whole `big` subtree

	stats := store_objgraph_stats(mut ms, ms.doc_order.len)
	assert stats.has_object_graph
	assert stats.object_count == ms.obj_sink.objects.len
	// two docs share a big subtree → logical (no-sharing) count strictly exceeds
	// the distinct objects actually stored → dedup ratio > 1.
	assert stats.logical_objects > i64(stats.distinct_objects), 'expected sharing: logical ${stats.logical_objects} vs distinct ${stats.distinct_objects}'
	assert stats.distinct_objects > 0
}

// the dedup walk is cached: a second stats call with no mutation in between does
// not change the cached fingerprint (and a mutation invalidates it).
fn test_objgraph_stats_cache_fingerprint() {
	mut ms := &MemStore{
		backend: 'cxpack'
		is_open: true
	}
	ti_put(mut ms, '[a [x 1]]')
	_ := store_objgraph_stats(mut ms, ms.doc_order.len)
	g_docs := ms.graph_stats_docs
	g_objs := ms.graph_stats_objects
	assert g_docs == 1
	// re-read with no mutation → fingerprint unchanged (cache hit).
	_ = store_objgraph_stats(mut ms, ms.doc_order.len)
	assert ms.graph_stats_docs == g_docs && ms.graph_stats_objects == g_objs

	// a mutation moves the fingerprint → next read recomputes.
	ti_put(mut ms, '[b [y 2]]')
	s2 := store_objgraph_stats(mut ms, ms.doc_order.len)
	assert ms.graph_stats_docs == 2
	assert s2.object_count > g_objs
}

// engine-level: object_graph_stats counts logical (with multiplicity) vs distinct.
fn test_object_graph_stats_engine() {
	mut sink := cxstore.ObjectSink{}
	doc := cx.parse('[order [id 1] [a [k "v"]] [a [k "v"]]]') or { panic('parse') }
	root := cxstore.store_document(mut sink, doc, cxstore.default_fanout)
	getter := fn [sink] (h []u8) ?[]u8 {
		return sink.get(h)
	}
	logical, distinct := cxstore.object_graph_stats(getter, [root])
	// the two identical `[a [k "v"]]` children collapse to one object set →
	// logical (counts both) strictly exceeds distinct (stores them once).
	assert logical > i64(distinct), 'logical ${logical} should exceed distinct ${distinct} given repeated subtree'
	assert distinct > 0
}

// /metrics: cxpack emits cxstore_store_objects + cxstore_store_dedup_ratio; the
// flat mem backend emits ONLY docs — no object-graph series (no fabricated zeros).
fn test_metrics_objgraph_series_gated_by_backend() {
	// cxpack mount registered directly (bypasses cap_guard, like the other
	// engine-level cxpack tests).
	mut cp := &MemStore{
		backend: 'cxpack'
		is_open: true
	}
	ti_put(mut cp, '[doc [x 1] [y 2]]')
	cp_id := store_register(cp)
	cp_handle := store_handle_element(cp_id, cp)

	// a flat (document-model) mount — file:// keeps the flat index, so it must emit
	// the docs gauge but NO object-graph series (mem is now the subtree model, so
	// file:// is the genuine flat example here).
	mut flat := &MemStore{
		backend: 'file'
		is_open: true
	}
	flat.docs['h1'] = '[a 1]'
	flat.doc_order << 'h1'
	flat_id := store_register(flat)
	flat_handle := store_handle_element(flat_id, flat)

	out := svc_store_internal_metrics({
		'graph': cp_handle
		'flat':  flat_handle
	})
	// docs gauge for both
	assert out.contains('cxstore_store_docs{store="graph",backend="cxpack"}'), out
	assert out.contains('cxstore_store_docs{store="flat",backend="file"}'), out
	// object-graph series ONLY for the cxpack mount
	assert out.contains('cxstore_store_objects{store="graph",backend="cxpack"}'), out
	assert out.contains('cxstore_store_dedup_ratio{store="graph",backend="cxpack"}'), out
	assert !out.contains('store="flat"') || !out.contains('cxstore_store_objects{store="flat"'), 'flat backend must not emit object-graph series (no fabricated zeros): ${out}'
	assert !out.contains('cxstore_store_objects{store="flat"'), out
	assert !out.contains('cxstore_store_dedup_ratio{store="flat"'), out
}

// ── source: vcx/platform/store_legacy_code_refusal_test.v ──
// A3 (RULED 2026-08-08): a legacy computation-identity-keyed code record —
// the retired `code:` key prefix / `C` record kind, whose key was never the
// hash of the stored bytes — is REFUSED LOUDLY at load on every substrate.
// No silent skip, no read-tolerance window. These tests craft the legacy
// records on disk exactly as the retired writer emitted them and pin the
// refusal on both persisted formats (flat index + pack manifest).

fn lcr_root(tag string) string {
	return os.join_path(os.temp_dir(), 'cx-legacy-code-${os.getpid()}-${tag}')
}

fn lcr_open(url string) cx.Node {
	caps_set_all()
	return store_open_impl(url, '', '', false, true, map[string]string{})
}

fn lcr_close(h cx.Node) {
	store_stdlib_builtin_inner('store-close', [h]) or {}
}

// flat index: a legacy `D`-record with a code:-prefixed key (the retired
// flat persistence form) refuses at open with the integrity class.
fn test_flat_index_refuses_legacy_code_record() {
	root := lcr_root('flat')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	h := lcr_open('document+file://${root}')
	assert !is_err_value(h), 'setup open failed: ${render_canonical(h)}'
	store_stdlib_builtin_inner('store-put-doc-text', [h, store_str('[order id=1]')]) or {
		panic('setup put: ${err}')
	}
	lcr_close(h)

	// append the legacy record exactly as the retired writer framed it
	src := '[?def f (\$x) \$x]'
	legacy := 'D\tcode:sha2-256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\t${src.len}\n${src}\n'
	idx := os.join_path(root, store_index_name)
	mut f := os.open_append(idx) or { panic('append: ${err}') }
	f.write_string(legacy) or { panic('write: ${err}') }
	f.close()

	got := lcr_open('document+file://${root}')
	assert is_err_value(got), 'legacy code: record must REFUSE at open, got a live handle'
	rendered := render_canonical(got)
	assert rendered.contains('CXER1120'), 'refusal must be the integrity class: ${rendered}'
	assert rendered.contains('legacy code'), 'refusal must NAME the legacy record: ${rendered}'
}

// pack manifest: a legacy `C` manifest line refuses at open the same way.
fn test_pack_manifest_refuses_legacy_code_record() {
	root := lcr_root('pack')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	h := lcr_open('file://${root}')
	assert !is_err_value(h), 'setup open failed: ${render_canonical(h)}'
	store_stdlib_builtin_inner('store-put-doc-text', [h, store_str('[order id=1]')]) or {
		panic('setup put: ${err}')
	}
	lcr_close(h)

	mp := os.join_path(root, cxpack_manifest)
	mut f := os.open_append(mp) or { panic('append: ${err}') }
	f.write_string('C\tcode:sha2-256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\t${'cc'.repeat(32)}\n') or {
		panic('write: ${err}')
	}
	f.close()

	got := lcr_open('file://${root}')
	assert is_err_value(got), 'legacy C manifest record must REFUSE at open, got a live handle'
	rendered := render_canonical(got)
	assert rendered.contains('legacy code record'), 'refusal must NAME the legacy record: ${rendered}'
}

// ── source: vcx/platform/store_lifecycle_wave3_test.v ──
// store_lifecycle_wave3_test.v — W3 lifecycle fixes (#183 cxobj open, #180/#199
// TLS+env config, #181 watchdog, #186/#211 drain, #187 read-timeout, #219 framing).
// Behavioral: drives store_open_impl / parse_service_config / the drain path.
// ── #183: a FRESH cxobj store opens via the public [$store:open] path ─────────

fn test_cxobj_fresh_open_via_public_path() {
	caps_set_all()
	root := os.join_path(os.temp_dir(), 'w3_cxobj_${os.getpid()}')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	// fresh open — previously tripped the partial-store guard (objects/ dir created
	// by the backend attach before the presence check).
	h := store_open_impl('file://${root}?encoding=object-per-key', '', '', false, true,
		map[string]string{})
	assert w3_err_code(h) == '', 'fresh cxobj open must succeed, got ${w3_err_code(h)}: ${w3_err_msg(h)}'
	// put → get round-trips
	sk := store_stdlib_builtin_inner('store-put-doc-text', [h, store_str('[doc [x 1]]')]) or {
		panic('put: ${err.msg()}')
	}
	sks := cx.scalar_value_str_public((sk as cx.ScalarNode).value)
	got := store_stdlib_builtin_inner('store-get-doc-text', [h, store_str(sks)]) or {
		panic('get: ${err.msg()}')
	}
	assert cx.scalar_value_str_public((got as cx.ScalarNode).value) == '[doc [x 1]]', 'cxobj round-trip'
	// reopen the now-populated store
	h2 := store_open_impl('file://${root}?encoding=object-per-key', '', '', false, true,
		map[string]string{})
	assert w3_err_code(h2) == '', 'cxobj reopen must succeed, got ${w3_err_code(h2)}'
	got2 := store_stdlib_builtin_inner('store-get-doc-text', [h2, store_str(sks)]) or {
		panic('get2: ${err.msg()}')
	}
	assert cx.scalar_value_str_public((got2 as cx.ScalarNode).value) == '[doc [x 1]]', 'cxobj reopen round-trip'
}

fn test_cxobj_encrypted_fresh_open() {
	caps_set_all()
	os.setenv('CX_STORE_KEK_w3k', 'a'.repeat(64), true)
	root := os.join_path(os.temp_dir(), 'w3_cxobj_enc_${os.getpid()}')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	// #183 + #184: encryption-at-rest is reachable now that cxobj opens.
	h := store_open_impl('file://${root}?encoding=object-per-key', '', '', false, true, {
		'encrypt-key-id': 'w3k'
	})
	assert w3_err_code(h) == '', 'encrypted cxobj open must succeed, got ${w3_err_code(h)}: ${w3_err_msg(h)}'
	sk := store_stdlib_builtin_inner('store-put-doc-text', [h, store_str('[secret [v "PLAINTEXTPROBE"]]')]) or {
		panic('put: ${err.msg()}')
	}
	sks := cx.scalar_value_str_public((sk as cx.ScalarNode).value)
	// the object files on disk must NOT contain the plaintext (sealed at rest).
	mut found_plain := false
	objdir := os.join_path(root, 'objects')
	if os.exists(objdir) {
		for sh in (os.ls(objdir) or { [] }) {
			sub := os.join_path(objdir, sh)
			if !os.is_dir(sub) {
				continue
			}
			for f in (os.ls(sub) or { [] }) {
				blob := os.read_bytes(os.join_path(sub, f)) or { continue }
				if blob.bytestr().contains('PLAINTEXTPROBE') {
					found_plain = true
				}
			}
		}
	}
	assert !found_plain, 'encrypted cxobj must NOT store plaintext on disk'
	// and it round-trips (decrypt)
	got := store_stdlib_builtin_inner('store-get-doc-text', [h, store_str(sks)]) or {
		panic('get: ${err.msg()}')
	}
	assert cx.scalar_value_str_public((got as cx.ScalarNode).value).contains('PLAINTEXTPROBE'), 'encrypted cxobj must decrypt on read'
}

