fn test_config_tls_parses_cert_key_ca() {
	c := parse_service_config('[cxstore-service [bind addr="h:1"] [tls cert="/etc/c.pem" key="/etc/k.pem" ca="/etc/ca.pem"] [stores [store name="s" url="mem://s"]]]') or {
