// ── #186 drain_complete is the live in-flight probe ───────────────────────────

fn test_drain_complete_bounded_semantics() {
	mut s := new_service_state()
	s.mark_ready()
	// not draining → drain_complete false
	assert !s.drain_complete(false)
	s.begin_drain()
	// draining, no in-flight → complete
	assert s.drain_complete(false)
	// draining, deadline reached → complete regardless
	assert s.drain_complete(true)
}

fn w3_err_code(n cx.Node) string {
	if n is cx.Element && n.name == 'err' {
		for a in n.attrs {
			if a.name == 'code' {
				return cx.scalar_value_str_public(a.value)
			}
		}
	}
	return ''
}

fn w3_err_msg(n cx.Node) string {
	if n is cx.Element && n.name == 'err' {
		for a in n.attrs {
			if a.name == 'message' {
				return cx.scalar_value_str_public(a.value)
			}
		}
	}
	return ''
}

// ── source: vcx/platform/store_modify_select_test.v ──
// store_modify_select_test.v — #134-1 (nested target via select) + #134-2
// (child-remove). Exercises the issue's exact repros against store_modify_apply.

fn parse_el(src string) cx.Element {
	doc := cx.parse(src) or { panic('parse ${src}: ${err}') }
	if doc.elements.len == 0 || doc.elements[0] !is cx.Element {
		panic('not an element: ${src}')
	}
	return doc.elements[0] as cx.Element
}

// #134-1: select="//t" sets the attr on the CHILD, not the root.
fn test_modify_select_targets_nested_child() {
	root := parse_el('[targets [t mmsi="111" sog="0"]]')
	act := parse_el('[set-attr select="//t" name=sog value="9"]')
	out := store_modify_apply(root, '//t', act) or { panic(err.msg()) }
	r := render_canonical(out)
	// the child t now has sog='9'
	assert r.contains("[t mmsi='111' sog='9']"), 'child not updated: ${r}'
	// the root targets did NOT get a stray sog attr
	assert r.starts_with('[targets ['), 'root gained a stray attr: ${r}'
	assert !r.contains("[targets sog="), 'sog leaked onto root: ${r}'
}

// #134-2: [remove select="//t"] deletes the matched child.
fn test_modify_remove_child() {
	root := parse_el('[targets [t mmsi="111"] [t mmsi="222"]]')
	act := parse_el('[remove select="//t"]')
	out := store_modify_apply(root, '//t', act) or { panic(err.msg()) }
	r := render_canonical(out)
	assert r == '[targets]', 'expected all t children removed, got: ${r}'
}

// #134-2: remove a specific keyed child (one of several) — descendant match.
fn test_modify_remove_is_scoped_to_matches() {
	root := parse_el('[doc [keep [v "k"]] [drop [v "d"]] [keep [v "k2"]]]')
	act := parse_el('[remove select="//drop"]')
	out := store_modify_apply(root, '//drop', act) or { panic(err.msg()) }
	r := render_canonical(out)
	assert !r.contains('drop'), 'drop not removed: ${r}'
	assert r.contains("[keep [v 'k']]") && r.contains("[keep [v 'k2']]"), 'keep nodes lost: ${r}'
}

// back-compat: no select edits the root element (the original behavior).
fn test_modify_no_select_edits_root() {
	root := parse_el('[targets [t mmsi="111"]]')
	act := parse_el('[set-attr name=count value="1"]')
	out := store_modify_apply(root, '', act) or { panic(err.msg()) }
	r := render_canonical(out)
	assert r.contains("[targets count='1'"), 'root not edited: ${r}'
}

// remove without a select is an error (can't remove the document root).
fn test_modify_remove_without_select_errors() {
	root := parse_el('[targets [t mmsi="111"]]')
	act := parse_el('[remove]')
	store_modify_apply(root, '', act) or { return } // expected error
	assert false, 'expected an error removing the root with no select'
}

// append into a nested match.
fn test_modify_append_nested() {
	root := parse_el('[doc [list [item "a"]]]')
	act := parse_el('[append select="//list" [item "b"]]')
	out := store_modify_apply(root, '//list', act) or { panic(err.msg()) }
	r := render_canonical(out)
	assert r.contains("[item 'a']") && r.contains("[item 'b']"), 'append into child failed: ${r}'
}

// ── source: vcx/platform/store_open_opts_map_test.v ──
// store_open_opts_map_test.v — #259: `store-open-opts` read opts from
// opts.attrs ONLY, but a CX map literal ({"k": v}) materializes its entries
// as CHILD ELEMENTS of the __cx_map__ envelope — so every opt passed as a CX
// map was silently dropped. For `encrypt-key-id` that meant the store was
// created PLAINTEXT where the caller asked for a sealed one (fail-open,
// violating store.md §9 fail-closed). These tests drive the REAL builtin with
// both entry shapes and assert the secret bytes never rest in the clear.

const oomt_kek = '00112233445566778899aabbccddeeff00112233445566778899aabbccddeeff'

const oomt_secret = 'oomt-plaintext-secret-0123456789abcdef'

fn oomt_dir_has_plaintext(dir string) bool {
	entries := os.ls(dir) or { return false }
	for f in entries {
		p := os.join_path(dir, f)
		if os.is_dir(p) {
			if oomt_dir_has_plaintext(p) {
				return true
			}
			continue
		}
		blob := os.read_bytes(p) or { continue }
		if blob.bytestr().contains(oomt_secret) {
			return true
		}
	}
	return false
}

fn oomt_open(dir string, opts_text string) cx.Node {
	opts := cx.parse(opts_text) or { panic('opts parse: ${err.msg()}') }.elements[0]
	url := cx.Node(cx.ScalarNode{ value: cx.ScalarValue('file://${dir}') })
	r := store_stdlib_builtin('store-open-opts', [url, cx.Node(opts)]) or {
		panic('store-open-opts returned none')
	}
	return r
}

fn oomt_seal_case(t string, opts_text string) {
	caps_set_all()
	dir := os.join_path(os.temp_dir(), 'cx_oomt_${t}_${os.getpid()}')
	os.rmdir_all(dir) or {}
	defer {
		os.rmdir_all(dir) or {}
	}
	os.setenv('CX_STORE_KEK_tenc1', oomt_kek, true)
	defer {
		os.unsetenv('CX_STORE_KEK_tenc1')
	}
	h := oomt_open(dir, opts_text)
	assert !is_err_value(h), 'open failed: ${render_canonical(h)}'
	sec := cx.Node(cx.ScalarNode{ value: cx.ScalarValue(oomt_secret) })
	ph := store_stdlib_builtin('store-put-doc', [h, sec]) or { panic('put none') }
	assert !is_err_value(ph), 'put failed: ${render_canonical(ph)}'
	// round-trip through the same handle
	got := store_stdlib_builtin('store-get-doc', [h, ph]) or { panic('get none') }
	assert render_canonical(got).contains(oomt_secret), 'roundtrip lost the doc'
	// THE point: nothing at rest carries the plaintext
	assert !oomt_dir_has_plaintext(dir), '${t}: PLAINTEXT AT REST — encrypt-key-id was dropped'
}

// the CX map-literal shape: entries are child elements of __cx_map__ (#259
// regression — this shape was silently ignored).
fn test_open_opts_encrypt_key_id_via_map_children_seals() {
	oomt_seal_case('children', '[__cx_map__ [encrypt-key-id tenc1]]')
}

// the attrs shape (pre-existing path) must keep sealing too.
fn test_open_opts_encrypt_key_id_via_attrs_seals() {
	oomt_seal_case('attrs', '[opts encrypt-key-id=tenc1]')
}

// ── source: vcx/platform/store_silent_partial_wave5_test.v ──
// store_silent_partial_wave5_test.v — W5 silent-partial guards (#185/#209 non-
// object-graph porcelain must error not fabricate success; #192 query predicate/
// attribute CXPath must match or fail-closed, never a lying empty result).

fn w5_open(url string) cx.Node {
	return store_open_impl(url, '', '', false, true, map[string]string{})
}

fn w5_err_code(n cx.Node) string {
	if n is cx.Element && n.name == 'err' {
		for a in n.attrs {
			if a.name == 'code' {
				return cx.scalar_value_str_public(a.value)
			}
		}
	}
	return ''
}

// register a synthetic columnar-backed handle (the guard checks ms.backend, no
// Arrow build needed to exercise the porcelain gate).
fn w5_columnar_handle() cx.Node {
	mut ms := &MemStore{
		url:     'document+file:///tmp/w5col?encoding=parquet'
		backend: 'columnar'
		is_open: true
		op_lock: sync_new()
	}
	id := store_register(ms)
	return store_handle_element(id, ms)
}

fn sync_new() &sync.Mutex {
	return sync.new_mutex()
}

// ── #209: columnar clone/push/pull → CXER1709 "use migrate", never objects=0 ──

fn test_columnar_porcelain_errors_not_silent() {
	caps_set_all()
	col := w5_columnar_handle()
	mem := w5_open('mem://w5-col-dst')
	// clone FROM columnar → hard error (source has no object identity).
	r_clone := store_stdlib_builtin('store-clone', [col, mem]) or {
		cx.Node(cx.ScalarNode{})
	}
	assert w5_err_code(r_clone) == 'cx-err:CXER1709', 'clone from columnar must be CXER1709 (§4 use migrate), got ${w5_err_code(r_clone)}'
	// push TO columnar → hard error (dest has no object identity).
	r_push := store_stdlib_builtin('store-push', [mem, col]) or { cx.Node(cx.ScalarNode{}) }
	assert w5_err_code(r_push) == 'cx-err:CXER1709', 'push to columnar must be CXER1709, got ${w5_err_code(r_push)}'
	// crucially: NOT a fabricated objects=0 success.
	assert w5_err_code(r_clone) != '', 'columnar clone must NOT return a *-result success'
}

// ── #185: remote byte-source porcelain → CXER1709, never phantom success ──────

fn test_remote_porcelain_errors_not_phantom() {
	caps_set_all()
	// a remote byte-source handle (ftp) has no object wire → porcelain must error.
	remote := w5_open('ftp://ftp.example.invalid/store/')
	if w5_err_code(remote) != '' {
		// open itself may defer connection; if it errored, skip (can't test the guard)
		return
	}
	mem := w5_open('mem://w5-remote-src')
	r := store_stdlib_builtin('store-push', [mem, remote]) or { cx.Node(cx.ScalarNode{}) }
	assert w5_err_code(r) == 'cx-err:CXER1709', 'push to a remote byte-source must be CXER1709 (#185 no phantom success), got ${w5_err_code(r)}'
}

// ── #192: query predicate + attribute CXPath ──────────────────────────────────

fn w5_query(local cx.Node, path string) cx.Node {
	return store_stdlib_builtin('store-query', [local, store_str(path)]) or {
		cx.Node(cx.ScalarNode{})
	}
}

fn w5_result_count(n cx.Node) int {
	mut c := 0
	if n is cx.Element {
		for it in n.items {
			if it is cx.Element && it.name == 'result' {
				c++
			}
		}
	}
	return c
}

fn test_query_predicate_matches() {
	caps_set_all()
	local := w5_open('mem://w5-query')
	store_stdlib_builtin('store-put-doc-text', [local, store_str('[users [user name="al"] [user name="bo"]]')]) or {
		panic('put')
	}
	// L97 flat relation: one [result doc= source= MATCH] tuple per MATCH —
	// the 2 user elements in the one doc are 2 tuples (the former doc-keyed
	// nesting counted 1 result per doc; honestly re-pinned at the cutover).
	names := w5_query(local, '//user')
	assert w5_result_count(names) == 2, '//user must yield one tuple per match (2 users), got ${w5_result_count(names)}'
	// predicate: only user[@name='al'] passes → 1 tuple
	pred := w5_query(local, "//user[= $_@name 'al']")
	assert w5_err_code(pred) == '', 'predicate query must not error: ${w5_err_code(pred)}'
	assert w5_result_count(pred) == 1, "//user[= \$_@name 'al'] must match (was silently ()), got ${w5_result_count(pred)}"
	// a predicate that matches nothing → genuinely 0 results (not an error)
	nomatch := w5_query(local, "//user[= $_@name 'zz']")
	assert w5_err_code(nomatch) == '', 'non-matching predicate is empty, not an error'
	assert w5_result_count(nomatch) == 0, 'non-matching predicate → 0 results'
	// attribute axis: //user/@name → one tuple per attribute value (2 users)
	attr := w5_query(local, '//user/@name')
	assert w5_err_code(attr) == '', 'attribute-axis query must not error'
	assert w5_result_count(attr) == 2, '//user/@name must yield one tuple per match (was silently ()), got ${w5_result_count(attr)}'
	// provenance attributes ride every tuple: doc= (content address) + source=
	// (store-url#cxpath)
	if names is cx.Element {
		first := names.items[0]
		if first is cx.Element {
			mut doc_attr := ''
			mut src_attr := ''
			for a in first.attrs {
				if a.name == 'doc' {
					doc_attr = cx.scalar_value_str_public(a.value)
				}
				if a.name == 'source' {
					src_attr = cx.scalar_value_str_public(a.value)
				}
			}
			assert doc_attr.starts_with('sha2-256:'), 'tuple doc= must carry the tagged content address, got ${doc_attr}'
			assert src_attr == 'mem://w5-query#//user', 'tuple source= must spell store-url#cxpath, got ${src_attr}'
		}
	}
}

// ── source: vcx/platform/store_subtree_objectmodel_test.v ──
// store_subtree_objectmodel_test.v — #129 foundation evidence. Proves the
// vcx/cxstore subtree object-graph engine delivers, at the code-module
// integration boundary (with render_canonical, the store's hash input), the
// three properties the subtree storage model must guarantee:
//
//   (1) canonical-text round-trip — a doc reconstructed from the object graph
//       re-renders to byte-identical canonical text, so the content hash
//       (cx_text_hash(render_canonical(...))) is preserved. This is the
//       "render_canonical <-> emit_node_bin" reconciliation that store_cxpack.v
//       flagged as the blocker; the probe cases show it holds.
//   (2) cross-document subtree dedup — an identical subtree in two unrelated
//       documents shares object(s).
//   (3) modify structural sharing — a one-field change reuses every untouched
//       subtree object; only the path from the change to the root is new.
//
// This validates the engine before the [$store] backend wiring (the next brick).

// obj_keys returns the set of object-hash keys produced by content-addressing a
// document into a fresh sink.
fn obj_keys(src string) map[string]bool {
	mut keys := map[string]bool{}
	doc := cx.parse(src) or { return keys }
	mut sink := cxstore.ObjectSink{}
	cxstore.store_document(mut sink, doc, cxstore.default_fanout)
	for k, _ in sink.objects {
		keys[k] = true
	}
	return keys
}

fn intersect_count(a map[string]bool, b map[string]bool) int {
	mut n := 0
	for k, _ in a {
		if k in b {
			n++
		}
	}
	return n
}

// (1) canonical-text round-trip across varied + adversarial constructs.
fn probe_rc_roundtrip(src string) (string, string) {
	doc := cx.parse(src) or { return 'PARSE_ERR: ${err}', '' }
	if doc.elements.len == 0 {
		return 'NO_ELEMENTS', ''
	}
	c0 := render_canonical(doc.elements[0])
	mut sink := cxstore.ObjectSink{}
	root := cxstore.store_document(mut sink, doc, cxstore.default_fanout)
	getter := fn [sink] (h []u8) ?[]u8 {
		return sink.get(h)
	}
	doc2 := cxstore.load_document_from(getter, root) or { return c0, 'LOAD_ERR: ${err}' }
	if doc2.elements.len == 0 {
		return c0, 'NO_ELEMENTS_AFTER'
	}
	c1 := render_canonical(doc2.elements[0])
	return c0, c1
}

fn test_subtree_canonical_text_roundtrip() {
	cases := [
		'[note id="x" [title "Hello"] [body "first"]]',
		'[db [meta [version 1] [name "store"]] [rec [id 1] [name "alice"] [tags [t "a"] [t "b"]]]]',
		'[m a=1 b="two" c=true [child [leaf 3.14]]]',
		'[x p="a b" q=\'single\' n=42 f=1.5 t=true]',
		'[doc [empty] [nested [deep [deeper "v"]]]]',
		'[el xmlns:b="urn:b" xmlns:a="urn:a" a:x="1" b:y="2"]',
		'[n neg=-5 z=0 f=-3.14 e=1.5e10 big=123456789012345678]',
		'[s a="he said \\"hi\\"" b="line1\\nline2" c="it\'s" d="tab\\there"]',
		'[p "leading text" [b "bold"] "trailing text"]',
		'[u name="café" emoji="🜨" cjk="日本語"]',
		'[doc [; a comment ] [keep "v"]]',
		'[f flag enabled="" zero=0]',
	]
	mut failures := []string{}
	for src in cases {
		c0, c1 := probe_rc_roundtrip(src)
		if c0 != c1 {
			failures << 'MISMATCH\n  src: ${src}\n  c0:  ${c0}\n  c1:  ${c1}'
		}
	}
	if failures.len > 0 {
		assert false, '\n' + failures.join('\n---\n')
	}
}

// (2) cross-document subtree dedup: an identical subtree in two unrelated docs
// shares object(s).
fn test_cross_doc_subtree_dedup() {
	d1 := '[doc1 [unique1 "u1"] [common [k "same"] [k2 "same2"]]]'
	d2 := '[doc2 [unique2 "u2"] [common [k "same"] [k2 "same2"]]]'
	common := intersect_count(obj_keys(d1), obj_keys(d2))
	assert common > 0, 'expected common subtree objects across unrelated docs, got 0'
}

// (3) modify structural sharing: a one-field deep change reuses untouched
// subtree objects — only the changed path is new.
fn test_modify_structural_sharing() {
	// A large untouched subtree (`keep`) + one small mutable field (`mut/v`), so
	// reuse dominates: only the v->root path should be rehashed.
	d := '[doc [keep [a "1"] [b "2"] [c "3"] [d "4"] [e "5"] [f "6"]] [mut [v "ORIGINAL"]]]'
	dp := '[doc [keep [a "1"] [b "2"] [c "3"] [d "4"] [e "5"] [f "6"]] [mut [v "CHANGED"]]]'

	d_alone := obj_keys(d)
	dp_alone := obj_keys(dp)

	// the untouched `keep` subtree contributes common objects to both versions.
	common := intersect_count(d_alone, dp_alone)
	assert common >= 3, 'expected the untouched subtree to share >=3 objects, got ${common}'

	// storing D' on top of D adds only the changed path (b/y + ancestors), far
	// fewer than D' has in total — i.e. untouched subtrees are reused, not rewritten.
	doc_d := cx.parse(d) or {
		assert false, 'parse d'
		return
	}
	doc_dp := cx.parse(dp) or {
		assert false, 'parse dp'
		return
	}
	mut sink := cxstore.ObjectSink{}
	cxstore.store_document(mut sink, doc_d, cxstore.default_fanout)
	before := sink.objects.len
	cxstore.store_document(mut sink, doc_dp, cxstore.default_fanout)
	added := sink.objects.len - before
	assert added < dp_alone.len, 'no reuse: D\' added ${added} objects, has ${dp_alone.len} total'
	// the changed path is small; most of D' was reused.
	assert added < common, 'expected fewer new objects (${added}) than common/reused (${common})'
}

// ── source: vcx/platform/store_verbatim_roundtrip_evidence_test.v ──
// EVIDENCE battery for the F1' letter (evidence-before-ruling, adopted
// 2026-08-08 after the S2 premise failure). This test PINS the current,
// observed round-trip behavior of the store's document path for
// representative document classes — it is documentation-of-fact, green
// against today's tree, cited verbatim by the F1' letter in the stream
// ledger. It asserts what IS, including the gap:
//
//   * structured cx DATA round-trips CANONICALIZED (by design — the
//     content address is the hash of canonical bytes; non-canonical
//     input is normalized);
//   * a def whose surface survives data-canonicalization round-trips;
//   * a def with a STRING-LITERAL body (the shipped dir-sync example's
//     greet def) does NOT round-trip byte-exact — data canonicalization
//     rewrites code's concrete syntax (params absorbed into a quoted
//     scalar), and the result no longer parses as the same program;
//   * the LOSSLESS formatter (cx_text_fmt) also does not preserve such
//     a def byte-exact (evidence against a fmt-based alternative).
//
// Consequence carried by the letter: code is an OPAQUE document (identity
// = raw bytes) and the store needs a general verbatim surface; the retired
// put-def was that path in disguise, mis-keyed by computation identity.
// When the verbatim surface lands, its own fixtures supersede the gap
// pins here (the data-canonicalization pins remain correct forever).

const ev_greet_def = "[?def greet (\$name) [str-format 'hello, {}' \$name]]"

const ev_simple_def = '[?def f (\$x) \$x]'

fn ev_store() cx.Node {
	return store_open_impl('mem://verbatim-evidence', '', '', false, true, map[string]string{})
}

fn ev_roundtrip(text string) string {
	h := ev_store()
	put := store_stdlib_builtin_inner('store-put-doc-text', [h, store_str(text)]) or {
		panic('put: ${err}')
	}
	hash := cx.scalar_value_str_public((put as cx.ScalarNode).value)
	got := store_stdlib_builtin_inner('store-get-doc-text', [h, store_str(hash)]) or {
		panic('get: ${err}')
	}
	if got is cx.ScalarNode {
		return cx.scalar_value_str_public(got.value)
	}
	if got is cx.TextNode {
		return got.value
	}
	panic('unexpected get-doc-text shape')
}

// Structured DATA: canonicalized round-trip is the CONTRACT (identity =
// canonical bytes). Non-canonical spacing normalizes; canonical input is
// byte-stable.
fn test_evidence_structured_data_round_trips_canonicalized() {
	assert ev_roundtrip('[order   id=1    total=99.5]') == '[order id=1 total=99.5]'
	canonical := '[order id=1 total=99.5]'
	assert ev_roundtrip(canonical) == canonical
}

// A def SIMPLE enough to survive data-canonicalization round-trips — this
// is the exact unrepresentative case the reverted S2 premise was declared
// on. Pinned to show WHY the premise looked true.
fn test_evidence_simple_def_survives() {
	got := ev_roundtrip(ev_simple_def)
	assert got == ev_simple_def, 'simple def: ${got}'
	// and its computation identity is preserved
	h1 := code.cx_code_tier2_hash(ev_simple_def) or { panic(err) }
	h2 := code.cx_code_tier2_hash(got) or { panic(err) }
	assert h1 == h2
}

// THE GAP: a def with a string-literal body — the shipped dir-sync
// example's greet def — is REWRITTEN by data canonicalization: the param
// list is absorbed into a quoted scalar and the result no longer parses
// as a def at all. Code's concrete syntax is NOT structured cx data.
fn test_evidence_string_literal_def_mangles_through_doc_path() {
	got := ev_roundtrip(ev_greet_def)
	assert got != ev_greet_def, 'expected the documented mangling, got byte-exact — if this now round-trips, the F1-prime evidence base changed: re-derive'
	// the mangled form is no longer the same program (parse_def refuses)
	if _ := cx.parse_def(got) {
		// If it still parses as a def, it must at least keep computation
		// identity to count as preserved — pin that it does NOT.
		h1 := code.cx_code_tier2_hash(ev_greet_def) or { panic(err) }
		h2 := code.cx_code_tier2_hash(got) or {
			return
		}
		assert h1 != h2, 'mangled def unexpectedly kept computation identity'
	}
}

// The LOSSLESS formatter is not a verbatim substitute either: cx_text_fmt
// of the greet def does not reproduce the source byte-exact (evidence
// against solving the gap with a fmt-canonical storage form).
fn test_evidence_lossless_fmt_is_not_verbatim_for_code() {
	fmtd := cx.cx_text_fmt(ev_greet_def) or { panic('fmt: ${err}') }
	assert fmtd.trim_space() != ev_greet_def, 'cx_text_fmt now reproduces the def byte-exact — re-examine the F1-prime evidence base'
}
